package com.adesa.attendance.vendor;
import org.junit.jupiter.api.Test;import java.util.*;import java.time.*;import java.nio.file.*;import com.lowagie.text.pdf.PdfReader;import com.lowagie.text.pdf.parser.PdfTextExtractor;import static org.assertj.core.api.Assertions.*;
class VendorPdfTest {
 @Test void brandedSignedPdfIncludesQuestionsConsentImagesAndLongAnswers()throws Exception{
  var answers=VendorRules.validate(VendorDemoFixtures.sample(0,"ENERGY"));answers.put("description",("Fictional engineering services, delivery and maintenance for presentation testing. ").repeat(55));answers.put("submissionTime",Instant.parse("2026-11-26T10:00:00Z").toString());answers.put("applicationReference","VND-ENG-DEMO0001");
  var profile=new LinkedHashMap<String,Object>();profile.put("answers",answers);profile.put("reference","VND-ENG-DEMO0001");profile.put("subsidiary","ENERGY");profile.put("status","UNDER_REVIEW");profile.put("banking_status","UNVERIFIED");profile.put("revision",1);profile.put("documents",List.of(Map.of("category","Company profile","filename","Fictional_Company_Profile.pdf","created_at","2026-11-26T10:00:00Z","ready",true)));profile.put("notes",List.of(Map.of("author","admin@vendor.example.test","createdAt","2026-11-26T10:00:00Z","body","Demonstration verification note; not an original vendor answer.")));
  byte[] pdf=VendorPdf.write(profile,VendorFiles.signature("Demo Signatory","CLASSIC"));assertThat(pdf).hasSizeGreaterThan(15000);
  try(var reader=new PdfReader(pdf)){assertThat(reader.getNumberOfPages()).isGreaterThanOrEqualTo(4);StringBuilder text=new StringBuilder();var extractor=new PdfTextExtractor(reader);for(int i=1;i<=reader.getNumberOfPages();i++)text.append(extractor.getTextFromPage(i));String content=text.toString().replaceAll("\\s+"," ");assertThat(content).contains("Vendor Acquisition Form","Registered business name","Account number","Electronic signature consent","authorised signatory","Not applicable","VND-ENG-DEMO0001","CONFIDENTIAL");assertThat(content).doesNotContain("https://storage","public/vendor");}
  String output=System.getProperty("vendor.demo.artifacts");if(output!=null){Path dir=Path.of(output);Files.createDirectories(dir);Files.write(dir.resolve("Vendor_Application_Fictional_Atlas_Engineering_VND-ENG-DEMO0001.pdf"),pdf);Files.write(dir.resolve("fictional-signature.png"),VendorFiles.signature("Demo Signatory","CLASSIC"));}
 }
 @Test void activeScriptsDisguisedAsPdfAreRejected()throws Exception{var bytes=new java.io.ByteArrayOutputStream();var document=new com.lowagie.text.Document();var writer=com.lowagie.text.pdf.PdfWriter.getInstance(document,bytes);document.open();document.add(new com.lowagie.text.Paragraph("Fictional test PDF"));writer.addJavaScript("app.alert('test');");document.close();assertThatThrownBy(()->VendorFiles.validate(bytes.toByteArray(),"company.pdf",false)).hasMessageContaining("Interactive scripts");}
 @Test void nestedInlineLaunchActionsAreRejected()throws Exception{
  var bytes=new java.io.ByteArrayOutputStream();var document=new com.lowagie.text.Document();var writer=com.lowagie.text.pdf.PdfWriter.getInstance(document,bytes);document.open();document.add(new com.lowagie.text.Paragraph("Fictional test PDF"));
  var action=new com.lowagie.text.pdf.PdfDictionary();action.put(com.lowagie.text.pdf.PdfName.S,new com.lowagie.text.pdf.PdfName("Launch"));var nested=new com.lowagie.text.pdf.PdfDictionary();nested.put(new com.lowagie.text.pdf.PdfName("Action"),action);writer.getExtraCatalog().put(new com.lowagie.text.pdf.PdfName("Nested"),nested);document.close();
  assertThatThrownBy(()->VendorFiles.validate(bytes.toByteArray(),"company.pdf",false)).hasMessageContaining("Interactive scripts");
 }
}
